<?php
declare(strict_types=1);
namespace App\Services\Pdf;

final class ReportTemplateService
{
    public const TYPES=[
        'admission-letter'=>'Admission Letter','job-letter'=>'Employee Job Letter','salary-slip'=>'Salary Slip','salary-sheet'=>'Salary Sheet',
        'fee-receipt'=>'Fee Receipt','fee-invoice'=>'Fee Invoice / Challan','report-card'=>'Student Report Card','certificate'=>'Certificate',
        'student-attendance'=>'Student Attendance','employee-attendance'=>'Employee Attendance','student-basic-list'=>'Student Basic List',
        'admissions'=>'Admission Details','contacts'=>'Parent Contact Details','account-statement'=>'Account Statement',
        'class-test-marksheet'=>'Class Test Mark Sheet','exam-gazette'=>'Class Examination Gazette','fee-defaulters'=>'Fee Defaulters',
    ];
    private const DEFAULTS=['primary_color'=>'#7A1632','accent_color'=>'#D9A441','page_size'=>'A4','page_orientation'=>'P','margin_mode'=>'normal','show_logo'=>1,'show_address'=>1,'show_phone'=>1,'show_website'=>1,'show_generated_date'=>1,'show_page_numbers'=>1,'subtitle'=>'','footer_text'=>'Generated by {{institute_name}} School Management System','settings_json'=>'{}'];

    public function defaults(string $type): array
    {
        if(!isset(self::TYPES[$type]))throw new \InvalidArgumentException('Unknown report template type.');
        $orientation=in_array($type,['admissions','contacts','class-test-marksheet','fee-defaulters'],true)?'L':'P';
        return array_replace(self::DEFAULTS,['page_orientation'=>$orientation])+['template_type'=>$type,'title'=>self::TYPES[$type],'body_html'=>'','settings'=>[]];
    }
    public function validate(string $type,array $input): array
    {
        $d=$this->defaults($type);$hex='/^#[0-9A-Fa-f]{6}$/';
        $title=trim((string)($input['title']??$d['title']));$subtitle=trim((string)($input['subtitle']??''));$footer=trim((string)($input['footer_text']??$d['footer_text']));
        if($title===''||mb_strlen($title)>120||mb_strlen($subtitle)>255||mb_strlen($footer)>500)throw new \InvalidArgumentException('Template text is invalid.');
        $primary=(string)($input['primary_color']??$d['primary_color']);$accent=(string)($input['accent_color']??$d['accent_color']);
        if(!preg_match($hex,$primary)||!preg_match($hex,$accent))throw new \InvalidArgumentException('Use valid six-digit hex colors.');
        $orientation=(string)($input['page_orientation']??'P');$size=(string)($input['page_size']??'A4');$margin=(string)($input['margin_mode']??'normal');
        if(!in_array($orientation,['P','L'],true)||!in_array($size,['A4','Letter'],true)||!in_array($margin,['normal','compact'],true))throw new \InvalidArgumentException('Invalid page settings.');
        $body=$this->sanitizeHtml((string)($input['body_html']??''));
        $signatureOne=mb_substr(trim((string)($input['signature_one']??'')),0,60);$signatureTwo=mb_substr(trim((string)($input['signature_two']??'')),0,60);
        return ['title'=>$title,'subtitle'=>$subtitle,'body_html'=>$body,'footer_text'=>$footer,'page_orientation'=>$orientation,'page_size'=>$size,'margin_mode'=>$margin,'primary_color'=>strtoupper($primary),'accent_color'=>strtoupper($accent),'show_logo'=>$this->flag($input,'show_logo'),'show_address'=>$this->flag($input,'show_address'),'show_phone'=>$this->flag($input,'show_phone'),'show_website'=>$this->flag($input,'show_website'),'show_generated_date'=>$this->flag($input,'show_generated_date'),'show_page_numbers'=>$this->flag($input,'show_page_numbers'),'settings_json'=>json_encode(['signature_one'=>$signatureOne,'signature_two'=>$signatureTwo],JSON_THROW_ON_ERROR)];
    }
    public function placeholders(string $type): array{return match($type){'admission-letter'=>['student_name','registration_no','class_name','father_name','institute_name'],'job-letter'=>['employee_name','employee_no','role','joining_date','institute_name'],'salary-slip'=>['employee_name','employee_no','salary_month','amount_paid','institute_name'],'fee-receipt'=>['student_name','registration_no','receipt_no','amount_paid','institute_name'],'certificate'=>['recipient_name','achievement','certificate_date','institute_name'],default=>['institute_name']};}
    public function renderText(string $value,array $values,string $type): string
    {
        $allowed=array_flip($this->placeholders($type));
        return preg_replace_callback('/\{\{([a-z0-9_]+)\}\}/i',static fn($m)=>isset($allowed[$m[1]])?htmlspecialchars((string)($values[$m[1]]??''),ENT_QUOTES,'UTF-8'):'',$value)??'';
    }
    public function sanitizeHtml(string $html): string{$html=preg_replace('#<(script|style|iframe|object|embed)[^>]*>.*?</\1>#is','',$html)??'';$html=strip_tags($html,'<p><br><strong><b><em><i><u><ul><ol><li><h2><h3>');return preg_replace('/\s+(on\w+|style|class|id)\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/i','',$html)??'';}
    private function flag(array $input,string $key): int{return isset($input[$key])&&in_array((string)$input[$key],['1','on','true'],true)?1:0;}
}
